draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw ancient fig tree
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50, H/2 - 50);
  ctx.stroke();

  // draw figs
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2 + 40, H/2 - 60, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 60, H/2 - 40, 10, 0, 2 * Math.PI);
  ctx.fill();

  // draw stick figure eating fig
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 20, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 20 + 20);
  ctx.lineTo(W/2 - 50, H/2 - 20 + 50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 20 + 50);
  ctx.lineTo(W/2 - 70, H/2 - 20 + 80); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 20 + 50);
  ctx.lineTo(W/2 - 30, H/2 - 20 + 80); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 20 + 40);
  ctx.lineTo(W/2 - 70, H/2 - 20 + 30); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 20 + 40);
  ctx.lineTo(W/2 - 30, H/2 - 20 + 30); // arm
  ctx.stroke();

  // animate eating
  ctx.beginPath();
  ctx.arc(W/2 - 50 + Math.sin(t) * 10, H/2 - 20 + 30, 5, 0, 2 * Math.PI); // fig
  ctx.fill();

  ctx.restore();
}
